var hand = gm.local_player().get("hand", [])
var atk = ""
for c in hand:
	var ct = String(c.get("cardType",""))
	if atk == "" and (ct == "offensive" or ct == "martialTheorem"):
		atk = String(c.get("id",""))
var opp = ""
for pid in gm.state.get("players", {}).keys():
	if String(pid) != gm.local_session_id:
		opp = String(pid)
kit.set_meta("_atk", atk)
kit.set_meta("_opp", opp)
if atk != "":
	cm.send_intent("play_card", {"cardId": atk, "target": {"kind": "opp", "id": opp}})
return {"atk": atk, "opp": opp}

if gm.state.get('phase') == 'draw' and gm.state.get('currentTurnPlayerId') == gm.local_session_id:
